inline const Glyph& glyph(unsigned size,char c){unsigned i=c=='-'?0:c==':'?11:c>='0'&&c<='9'?unsigned(c-'0')+1:0;return (size==68?font68:size==52?font52:font34)[i];}
inline uint16_t blend(uint16_t fg,uint16_t bg,unsigned a){unsigned r=(((fg>>11)&31)*a+((bg>>11)&31)*(15-a)+7)/15,g=(((fg>>5)&63)*a+((bg>>5)&63)*(15-a)+7)/15,b=((fg&31)*a+(bg&31)*(15-a)+7)/15;return uint16_t((uint32_t(r)<<11)|(uint32_t(g)<<5)|b);}
template<class LCD> void character(LCD& lcd,int x,int y,int slot,char c,unsigned size,uint16_t ink,uint16_t bg){const auto& g=glyph(size,c);x+=(slot-int(g.w))/2;lcd.startWrite();for(unsigned row=0;row<g.h;++row){unsigned col=0;while(col<g.w){auto sample=[&](unsigned at){unsigned p=row*g.w+at;uint8_t v=alpha[g.offset+p/2];return unsigned((p&1)?v&15:v>>4);};unsigned a=sample(col),start=col++;while(col<g.w&&sample(col)==a)++col;if(a)lcd.writeFillRect(x+start,y+row,col-start,1,blend(ink,bg,a));}}lcd.endWrite();}
template<class LCD> void face(LCD& lcd,int x,int y,int slot,int colonSlot,unsigned size,const char* value,uint16_t ink,uint16_t bg){for(unsigned i=0;i<5;++i){int w=i==2?colonSlot:slot;character(lcd,x,y,w,value[i],size,ink,bg);x+=w;}}
